EDITS = ((TBODY_OLD, TBODY_NEW), (LD_OLD, LD_NEW), (H3_OLD, H3_NEW))


def apply(s):
    """вернуть страницу с новыми ценами; если правка уже есть — без изменений"""
    for old, new in EDITS:
        if new in s and old not in s:
            continue
        assert s.count(old) == 1, 'на странице не найден (или найден не один раз) фрагмент: ' + old[:80]
        s = s.replace(old, new, 1)
    return s


def main():
    files = [pathlib.Path(f) for f in sys.argv[1:]] or [PAGE]
    for f in files:
        s = f.read_text(encoding='utf-8')
        n = apply(s)
        if n != s:
            f.write_text(n, encoding='utf-8')
        print(f'{f}: ' + ('цены обновлены' if n != s else 'уже обновлено'))


if __name__ == '__main__':
    main()
